import itertools
import networkx as nx

def count_cliques(G, k):
    count = 0
    for nodes in itertools.combinations(G.nodes(), k):
        if G.subgraph(nodes).number_of_edges() == k * (k - 1) // 2:
            count += 1
    return count

def test_graphs():
    results = []
    # Try complete graphs Kn
    for n in range(4, 20):
        G = nx.complete_graph(n)
        f = count_cliques(G, 3)
        g = count_cliques(G, 4)
        if f > 0:
            results.append(g**3 / f**4)

    # Try complete multipartite graphs
    for n in range(2, 10):
        for m in range(2, 10):
            # Complete multipartite graphs are’t easily generated for all cases.
            # Let's just do balanced ones first.
            G = nx.complete_multipartite_graph([n]*m)
            f = count_cliques(G, 3)
            g = count_cliques(G, 4)
            if f > 0:
                results.append(g**3 / f**4)

    # Try some random graphs
    for n in range(5, 15):
        for p in [0.3, 0.5, 0.7]:
            for _ in range(10):
                G = nx.erdos_renyi_graph(n, p)
                f = count_cliques(G, 3)
                g = count_cliques(G, 4)
                if f > 0:
                    results.append(g**3 / f**4)

    return results

res = test_graphs()
print(max(res))
